// Canonical dossier fields and cross-dossier reminders.
let assetCategory='vehicles',assetSearch='',assetType='all',assetCondition='all',assetAttachment='all',assetFollowup='all',assetFiltersOpen=false,personCategory='Tous',alertTab='open';
const fieldGroups=[
['Identité légale',[['name','Dénomination légale','text',true],['tradeName','Nom commercial'],['legalForm','Forme juridique'],['vat','Numéro de TVA'],['enterpriseNumber','Numéro d’entreprise'],['created','Date de constitution','date'],['sector','Activité principale'],['activityCodes','Codes d’activité déclarés'],['size','Effectif'],['region','Région'],['country','Pays']]],
['Siège et coordonnées',[['street','Rue et numéro'],['postcode','Code postal'],['city','Commune'],['operatingAddress','Adresse d’exploitation (si différente)'],['phone','Téléphone','tel'],['email','Adresse e-mail','email'],['website','Site internet','url']]],
['Direction et interlocuteurs',[['manager','Dirigeant / représentant'],['managerEmail','E-mail du dirigeant','email'],['adminContact','Responsable administratif'],['adminPhone','Téléphone administratif','tel'],['accountant','Bureau comptable'],['accountantEmail','E-mail comptable','email'],['socialOffice','Secrétariat social'],['socialReference','Référence client du secrétariat social']]],
['Facturation et banque',[['billingAddress','Adresse de facturation'],['billingEmail','E-mail de facturation','email'],['bank','Banque'],['iban','IBAN'],['bic','BIC'],['paymentTerms','Conditions de paiement habituelles']]],
['Assurances et suivi de l’entreprise',[['broker','Courtier / contact assurances'],['brokerPhone','Téléphone du courtier','tel'],['companyInsurance','Assurance de l’entreprise / référence'],['preventionContact','Service de prévention / contact'],['companyNotes','Informations complémentaires']]]
];
Object.assign(company,{tradeName:'Atelier Démo',legalForm:'SRL',vat:'',enterpriseNumber:'',created:'2021-06-01',country:'Belgique',city:'Namur',postcode:'5000'});
people.forEach(p=>p.category=p.role==='Administration'?'Employé':p.role==='Apprenti'?'Apprenti':'Ouvrier');
assets.forEach(a=>{a.group=a.category.includes('Camion')?'vehicles':'tools';a.condition='En service';a.repairNote='';a.vehicle=a.group==='vehicles'?{registration:a.id===1?'DÉMO-001':'DÉMO-002',model:a.id===1?'Volkswagen Crafter':'Iveco Daily',firstRegistration:a.start,mileage:a.id===1?58000:29000,insurer:'Assurances Démo',policy:'AUTO-DEMO-00'+a.id,insuranceEnd:a.id===1?'2026-10-15':'2027-01-14',inspection:a.id===1?'2026-09-25':'2026-11-12'}:null;});
assets.push({id:5,name:'Nacelle en location',category:'Machine',group:'tools',mode:'Location',provider:'Location Démo',reference:'LOC-2026-041',start:'2026-09-20',end:'2026-09-30',monthly:420,responsible:'Antoine Simon',attached:'Chantier · Maison Dumas',contents:'Nacelle électrique + chargeur',condition:'En service',repairNote:'',history:[{date:'2026-09-20',text:'Début de location. Retour prévu le 30 septembre.'}],docs:['Contrat LOC-2026-041']});
assets[3].condition='À réparer';assets[3].repairNote='Fuite sur le raccord de sortie, diagnostic à prévoir.';
let reminders=tasks.map(t=>({id:'task-'+t.id,title:t.title,date:t.date,state:t.state,kind:t.kind,owner:t.owner,note:t.note,linkType:t.id===2?'asset':t.id===1?'person':'company',linkId:t.id===2?1:t.id===1?3:0,completedAt:t.state==='done'?reference:'',legacyId:t.id}));
Object.assign(reminders.find(r=>r.id==='task-2'),{title:'Contrôle technique · Crafter 01',kind:'Contrôle technique',sourceField:'inspection'});
reminders.push({id:'vehicle-insurance-1',title:'Assurance · Crafter 01',date:'2026-10-15',state:'todo',kind:'Assurance',owner:'Thomas Laurent',note:'Vérifier le renouvellement et l’attestation avec l’assureur.',linkType:'asset',linkId:1,sourceField:'insuranceEnd'}, {id:'vehicle-inspection-2',title:'Contrôle technique · Daily 02',date:'2026-11-12',state:'todo',kind:'Contrôle technique',owner:'Antoine Simon',note:'Date d’exemple à confirmer sur les documents du véhicule.',linkType:'asset',linkId:2,sourceField:'inspection'}, {id:'vehicle-insurance-2',title:'Assurance · Daily 02',date:'2027-01-14',state:'todo',kind:'Assurance',owner:'Antoine Simon',note:'Vérifier les conditions de renouvellement.',linkType:'asset',linkId:2,sourceField:'insuranceEnd'}, {id:'training-1',title:'Formation travail en hauteur · Mehdi',date:'2026-09-29',state:'todo',kind:'Formation',owner:'Thomas Laurent',note:'Confirmer la réservation, puis conserver l’attestation dans le dossier du salarié.',linkType:'person',linkId:3}, {id:'checkup-1',title:'Check-up à organiser · Thomas',date:'2026-10-06',state:'todo',kind:'Check-up',owner:'Sophie Bernard',note:'Vérifier la date du rendez-vous. Aucune donnée médicale n’est enregistrée ici.',linkType:'person',linkId:1}, {id:'rental-5',title:'Retour de location · Nacelle',date:'2026-09-30',state:'todo',kind:'Fin de location',owner:'Antoine Simon',note:'Préparer le retour et l’état des lieux.',linkType:'asset',linkId:5,sourceField:'end'}, {id:'repair-4',title:'Réparation · Compresseur atelier',date:'2026-09-24',state:'todo',kind:'Réparation',owner:'Antoine Simon',note:assets[3].repairNote,linkType:'asset',linkId:4});
function reminderLabel(r){return r.linkType==='asset'?assets.find(a=>a.id===r.linkId)?.name||'Bien':r.linkType==='person'?getPerson(r.linkId)?.name||'Salarié':company.name}
function reminderState(r){return r.state==='done'?['Terminée','green']:r.state==='waiting'?['En attente','warn']:r.date<reference?['En retard','red']:['À traiter','warn']}
function reminderRows(list){return list.length?list.map(r=>{const st=reminderState(r);return `<button class="task alert-row" onclick="showReminder('${jsString(r.id)}')"><span class="alert-date"><b>${new Date(r.date+'T12:00:00').getDate()}</b><small>${new Date(r.date+'T12:00:00').toLocaleDateString('fr-BE',{month:'short'})}</small></span><span class="task-text"><strong>${esc(r.title)}</strong><small>${esc(reminderLabel(r))} · ${esc(r.owner||'Responsable à définir')}</small></span><span class="badge">${esc(r.kind)}</span><span class="badge ${st[1]}">${st[0]}</span><span aria-hidden="true">↗</span></button>`}).join(''):'<div class="empty">Aucune alerte dans cette catégorie.</div>'}
function openReminders(){return reminders.filter(r=>r.state!=='done').sort((a,b)=>a.date.localeCompare(b.date))}
const originalPlanning=planning;
planning=function(){const pending=openReminders(),late=pending.filter(r=>r.date<reference).length;const board=originalPlanning();const start=board.indexOf('<div class="datebar">'),end=board.indexOf('<section class="bottom-strip">');return heading('Vue d’ensemble','Les alertes à traiter, puis les équipes sur leurs chantiers.',false)+`<section class="alert-panel"><div class="panel-head"><div><p class="eyebrow">RIEN NE DISPARAÎT SANS SUIVI</p><h2>Alertes de l’entreprise <span class="count">${pending.length}</span></h2></div><div class="alert-controls">${late?`<span class="badge red">${late} en retard</span>`:''}<button class="btn primary" onclick="reminderForm()">+ Ajouter une alerte</button></div></div><p class="alert-explainer">Les alertes restent ici, même en attente ou en retard, jusqu’à leur clôture. Les dates d’exemple sont à confirmer.</p><div class="alert-list">${reminderRows(pending)}</div><div class="alert-footer"><button class="link" onclick="alertTab='done';navigate('actions')">Voir les alertes terminées →</button><span>Dates de référence : ${fullDate(reference)}</span></div></section><div class="section-heading"><h2>Équipes & chantiers</h2><button class="btn" onclick="assignForm()">+ Affecter une équipe</button></div>${board.slice(start,end)}`};
actions=function(){const list=reminders.filter(r=>alertTab==='done'?r.state==='done':alertTab==='waiting'?r.state==='waiting':r.state!=='done').sort((a,b)=>a.date.localeCompare(b.date));return heading('Alertes & suivi','Une même alerte sur l’accueil et dans le dossier concerné.',false)+`<div class="section-heading"><h2>Échéances et actions</h2><button class="btn primary" onclick="reminderForm()">+ Ajouter une alerte</button></div><section class="panel"><div class="tabs">${[['open','À traiter'],['waiting','En attente'],['done','Terminées']].map(([v,l])=>`<button class="${alertTab===v?'selected':''}" onclick="alertTab='${v}';render()">${l} (${reminders.filter(r=>v==='done'?r.state==='done':v==='waiting'?r.state==='waiting':r.state!=='done').length})</button>`).join('')}</div>${reminderRows(list)}</section>`};
function showReminder(id){const r=reminders.find(r=>r.id===id);if(!r)return;modal(r.title,`<span class="badge ${reminderState(r)[1]}">${reminderState(r)[0]}</span><p>${esc(r.note||'Aucune note ajoutée.')}</p><div class="detail-row"><span>Date à suivre</span><b>${fullDate(r.date)}</b></div><div class="detail-row"><span>Responsable</span><b>${esc(r.owner)}</b></div><div class="detail-row"><span>Dossier associé</span><button class="link" onclick="openReminderDossier('${jsString(r.id)}')">${esc(reminderLabel(r))} ↗</button></div>${r.completedAt?`<div class="detail-row"><span>Clôturée le</span><b>${fullDate(r.completedAt.slice(0,10))}</b></div>`:''}<p class="notice">La mise en attente conserve l’alerte sur la vue d’ensemble. La clôture la déplace dans l’historique.</p><div class="modal-actions"><button class="btn" onclick="reminderForm('${jsString(id)}')">Modifier</button>${r.state==='done'?`<button class="btn primary" onclick="changeReminder('${jsString(id)}','todo')">Rouvrir</button>`:`<button class="btn" onclick="changeReminder('${jsString(id)}','waiting')">En attente</button><button class="btn primary" onclick="changeReminder('${jsString(id)}','done')">Marquer traitée</button>`}</div>`)}
function openReminderDossier(id){const r=reminders.find(r=>r.id===id);if(r.linkType==='asset')showAsset(r.linkId);else if(r.linkType==='person')personForm(r.linkId);else{closeModal();navigate('company')}}
function changeReminder(id,state){const r=reminders.find(r=>r.id===id);if(!r||!['todo','waiting','done'].includes(state))throw Error('Alerte invalide');r.state=state;r.completedAt=state==='done'?new Date().toISOString():'';if(r.legacyId){const t=tasks.find(t=>t.id===r.legacyId);if(t)t.state=state}closeModal();render();toast(state==='done'?'Alerte classée dans l’historique.':'Alerte conservée sur l’accueil.')}
function reminderForm(id='',type='company',linkId=0){const r=reminders.find(r=>r.id===id)||{title:'',date:reference,kind:'Formation',owner:'',linkType:type,linkId,note:''};modal(id?'Modifier l’alerte':'Nouvelle alerte',`<form onsubmit="saveReminder(event,'${jsString(id)}')"><label>Intitulé<input name="title" required maxlength="150" value="${esc(r.title)}"></label><div class="form-two"><label>Catégorie<select name="kind">${[...new Set(['Formation','Check-up','Contrôle technique','Assurance','Entretien','Réparation','Fin de location','Fin de contrat','Administratif',r.kind])].map(k=>`<option ${k===r.kind?'selected':''}>${esc(k)}</option>`).join('')}</select></label><label>Date<input name="date" type="date" required value="${r.date}"></label></div><label>Dossier concerné<select name="link"><option value="company:0">Entreprise</option><optgroup label="Personnel">${people.map(p=>`<option value="person:${p.id}" ${r.linkType==='person'&&r.linkId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</optgroup><optgroup label="Biens & véhicules">${assets.map(a=>`<option value="asset:${a.id}" ${r.linkType==='asset'&&r.linkId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</optgroup></select></label><label>Responsable<input name="owner" required maxlength="80" value="${esc(r.owner)}"></label><label>Notes<textarea name="note" rows="3" maxlength="1000">${esc(r.note)}</textarea></label><div class="modal-actions"><button class="btn primary">Enregistrer l’alerte</button></div></form>`)}
function saveReminder(e,id){e.preventDefault();const f=new FormData(e.target);if(!f.get('title').trim()||!f.get('owner').trim())return;const [linkType,link]=f.get('link').split(':');const data={title:f.get('title').trim(),date:f.get('date'),kind:f.get('kind'),owner:f.get('owner').trim(),note:f.get('note').trim(),linkType,linkId:+link};let r=reminders.find(r=>r.id===id);if(r){if(r.linkType!==data.linkType||r.linkId!==data.linkId)delete r.sourceField;Object.assign(r,data);if(r.sourceField&&r.linkType==='asset'){const a=assets.find(a=>a.id===r.linkId);if(['inspection','insuranceEnd'].includes(r.sourceField)&&a.vehicle)a.vehicle[r.sourceField]=r.date;else if(r.sourceField==='end')a.end=r.date}}else reminders.push({id:'reminder-'+crypto.randomUUID(),...data,state:'todo',completedAt:''});closeModal();render();toast('Alerte enregistrée et reliée à son dossier.')}
companyView=function(){const count=fieldGroups.flatMap(g=>g[1]).filter(([k])=>company[k]?.trim?.()).length,totalFields=fieldGroups.flatMap(g=>g[1]).length;return heading('Toutes les informations de l’entreprise.','Identité, TVA, coordonnées, interlocuteurs, banque et assurances.',false)+`<form class="company-form" onsubmit="saveCompany(event)"><div class="company-save"><span>${count} / ${totalFields} champs renseignés <small>Complétez les informations pertinentes pour votre entreprise.</small></span><button class="btn primary">Enregistrer la fiche entreprise</button></div><div class="company-sections">${fieldGroups.map(([label,fields],i)=>`<section class="panel company-section"><div class="panel-head"><span class="section-number">0${i+1}</span><h2>${label}</h2></div><div class="form-two">${fields.map(([key,label,type='text',req=false])=>`<label>${label}${req?' *':''}<input name="${key}" type="${type}" ${req?'required':''} maxlength="${key==='companyNotes'?1000:200}" value="${esc(company[key]||'')}" placeholder="${key==='vat'?'BE0123456789':key==='enterpriseNumber'?'0123.456.789':''}"></label>`).join('')}</div></section>`).join('')}</div><p class="notice">Les numéros de TVA et d’entreprise sont renseignés manuellement. Aucune validation auprès de la BCE ou de VIES n’est réalisée.</p><p id="companyError" class="form-error" role="alert"></p><div class="modal-actions"><button class="btn primary">Enregistrer la fiche entreprise</button></div></form>`};
saveCompany=function(e){e.preventDefault();const f=new FormData(e.target);if(!f.get('name').trim()){document.querySelector('#companyError').textContent='La dénomination est nécessaire.';return}for(const [key] of fieldGroups.flatMap(g=>g[1]))company[key]=f.get(key).trim();document.querySelector('.workspace').firstChild.textContent=company.name;render();toast('Fiche entreprise mise à jour.')};
function personTable(ids){const ps=ids.map(getPerson).filter(Boolean).filter(p=>personCategory==='Tous'||p.category===personCategory);return ps.length?`<div class="data-table"><table><thead><tr><th>Nom</th><th>Statut / fonction</th><th>Contrat</th><th>Date d’entrée</th><th>Fin du contrat</th><th>Formations</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><button class="person-cell" onclick="personForm(${p.id})">${face(p)}<span><strong>${esc(p.name)}</strong><small>Anniversaire · ${p.birth?new Date(p.birth+'T12:00:00').toLocaleDateString('fr-BE',{day:'numeric',month:'long'}):'À renseigner'}</small></span></button></td><td>${esc(p.category||'Ouvrier')}<small>${esc(p.role)}</small></td><td><span class="badge ${p.contract==='CDD'?'warn':''}">${esc(p.contract)}</span></td><td>${fullDate(p.start)}</td><td>${fullDate(p.end)}</td><td><span class="training-count">${p.training.length} déclarée(s)</span></td><td><button class="link" onclick="personForm(${p.id})" aria-label="Ouvrir la fiche de ${esc(p.name)}">Ouvrir ↗</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Aucune personne dans cette catégorie.</div>'}
peopleView=function(){const assigned=new Set(teams.flatMap(t=>t.members));return heading('Personnel & équipes attitrées','Les personnes, leur contrat et leur place dans l’entreprise.',false)+`<div class="section-heading"><div class="filter-pills">${[['Tous','Tout le personnel'],['Ouvrier','Ouvriers'],['Employé','Employés'],['Apprenti','Apprentis']].map(([v,l])=>`<button class="${v===personCategory?'selected':''}" onclick="personCategory='${v}';render()">${l}</button>`).join('')}</div><div class="alert-controls"><button class="btn" onclick="personForm()">+ Ajouter une personne</button><button class="btn primary" onclick="teamForm()">+ Créer une équipe</button></div></div>${teams.map(t=>`<section class="panel team-table"><div class="panel-head"><div><p class="eyebrow">ÉQUIPE ATTITRÉE</p><h2>${esc(t.name)} <span class="count">${t.members.length}</span></h2></div><button class="btn" onclick="teamForm(${t.id})">Modifier la composition</button></div>${personTable(t.members)}</section>`).join('')}<section class="panel team-table"><div class="panel-head"><div><p class="eyebrow">AUTRES COLLABORATEURS</p><h2>Sans équipe attitrée</h2></div></div>${personTable(people.filter(p=>!assigned.has(p.id)).map(p=>p.id))}</section>`};
const personFormBase=personForm,savePersonBase=savePerson;
personForm=function(id){personFormBase(id);const form=document.querySelector('#modalbody form');const p=getPerson(id);const details=document.createElement('div');details.className='professional-fields';details.innerHTML=`<p class="form-section-title">Profil professionnel</p><div class="form-two"><label>Type de personnel<select name="category">${['Ouvrier','Employé','Apprenti','Stagiaire','Intérimaire'].map(s=>`<option ${s===(p?.category||'Ouvrier')?'selected':''}>${s}</option>`).join('')}</select></label><label>Corps de métier principal<input name="trade" maxlength="80" placeholder="Ex. maçon, couvreur, plafonneur" value="${esc(p?.trade||'')}"></label><label>Qualification / niveau<input name="qualification" maxlength="80" placeholder="Ex. Q1, Q2, manœuvre spécialisé" value="${esc(p?.qualification||'')}"></label><label>Autres métiers ou compétences<input name="otherTrades" maxlength="200" placeholder="Ex. charpente, bardage" value="${esc((p?.otherTrades||[]).join(', '))}"></label></div>`;form.prepend(details);if(id){const div=document.createElement('section');div.className='person-alerts';div.innerHTML=`<div class="section-heading"><h3>Formations & échéances</h3><button type="button" class="link" onclick="reminderForm('','person',${id})">+ Ajouter</button></div>${reminderRows(reminders.filter(r=>r.linkType==='person'&&r.linkId===id&&r.state!=='done'))}`;form.after(div)}};
savePerson=function(e,id){const f=new FormData(e.target),extra={category:f.get('category'),trade:f.get('trade').trim(),qualification:f.get('qualification').trim(),otherTrades:f.get('otherTrades').split(',').map(x=>x.trim()).filter(Boolean)};savePersonBase(e,id);if(document.querySelector('#modal').open)return;const p=id?getPerson(id):people.at(-1);Object.assign(p,extra);render()};
function isVehicle(a){return a.group==='vehicles'}
function categoryAssets(key){return assets.filter(a=>key==='vehicles'?isVehicle(a):key==='tools'?a.group==='tools':key==='rentals'?a.mode==='Location':key==='repairs'?a.condition==='À réparer'||a.condition==='En réparation'||Boolean(a.repairNote)||Array.isArray(a.issues)&&a.issues.some(issue=>!['resolved','closed','done','traité','résolu'].includes(String(issue.status||'').toLocaleLowerCase('fr-BE'))):false)}
function assetHasActiveFollowup(a){return reminders.some(r=>r.linkType==='asset'&&r.linkId===a.id&&r.state!=='done')||Boolean(a.repairNote)||Array.isArray(a.issues)&&a.issues.some(issue=>!['resolved','closed','done','traité','résolu'].includes(String(issue.status||'').toLocaleLowerCase('fr-BE')))}
function assetFilterCount(){return (String(assetSearch||'').trim()?1:0)+[assetType,assetCondition,assetAttachment,assetFollowup].filter(value=>value!=='all').length}
function assetFilterValues(list,key){return [...new Set(list.map(a=>key==='attached'?(a.attached||'Sans rattachement'):a[key]).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),'fr-BE'))}
function assetFilteredList(list){const query=String(assetSearch||'').trim().toLocaleLowerCase('fr-BE');return list.filter(a=>{const search=[a.name,a.category,a.condition,a.attached,a.responsible,a.provider,a.reference,a.vehicle?.registration,a.vehicle?.model].filter(Boolean).join(' ').toLocaleLowerCase('fr-BE');if(query&&!search.includes(query))return false;if(assetType!=='all'&&a.category!==assetType)return false;if(assetCondition!=='all'&&a.condition!==assetCondition)return false;if(assetAttachment!=='all'&&(a.attached||'Sans rattachement')!==assetAttachment)return false;const followed=assetHasActiveFollowup(a);if(assetFollowup==='active'&&!followed)return false;if(assetFollowup==='none'&&followed)return false;return true})}
function closeAssetFilterSheet(){assetFiltersOpen=false;if(document.getElementById('asset-filter-sheet')?.dataset.open==='true')SocleUI.CompactFilterBar.setSheetOpen('asset-filter-sheet',false)}
function setAssetCategory(key){closeAssetFilterSheet();assetCategory=key;assetSearch='';assetType='all';assetCondition='all';assetAttachment='all';assetFollowup='all';render()}
function setAssetSearch(value){assetSearch=String(value||'');render();requestAnimationFrame(()=>{const input=document.querySelector('#asset-search');if(input){input.focus();const end=input.value.length;input.setSelectionRange?.(end,end)}})}
function setAssetFilter(name,value){if(name==='type')assetType=value;else if(name==='condition')assetCondition=value;else if(name==='attachment')assetAttachment=value;else if(name==='followup')assetFollowup=value;else return;closeAssetFilterSheet();render()}
function resetAssetFilters(){closeAssetFilterSheet();assetSearch='';assetType='all';assetCondition='all';assetAttachment='all';assetFollowup='all';render()}
function toggleAssetFilters(trigger,force){assetFiltersOpen=SocleUI.CompactFilterBar.toggleSheet('asset-filter-sheet',trigger,force);return assetFiltersOpen}
function assetFilterOptions(values,current,allLabel){return `<option value="all" ${current==='all'?'selected':''}>${esc(allLabel)}</option>${values.map(value=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(value)}</option>`).join('')}`}
function assetMarkupNode(markup){return SocleUI.fromLegacyMarkup(markup).firstElementChild}
function assetFilterBarHTML(){
  const base=categoryAssets(assetCategory),activeFilters=assetFilterCount();
  const search=assetMarkupNode(`<input id="asset-search" type="search" data-label="Recherche" value="${esc(assetSearch)}" placeholder="Nom, immatriculation, responsable…" autocomplete="off" oninput="setAssetSearch(this.value)">`);
  const controls=[
    assetMarkupNode(`<select id="asset-filter-type" data-label="Type" onchange="setAssetFilter('type',this.value)">${assetFilterOptions(assetFilterValues(base,'category'),assetType,'Tous les types')}</select>`),
    assetMarkupNode(`<select id="asset-filter-condition" data-label="État" onchange="setAssetFilter('condition',this.value)">${assetFilterOptions(assetFilterValues(base,'condition'),assetCondition,'Tous les états')}</select>`),
    assetMarkupNode(`<select id="asset-filter-attachment" data-label="Rattachement" onchange="setAssetFilter('attachment',this.value)">${assetFilterOptions(assetFilterValues(base,'attached'),assetAttachment,'Tous les rattachements')}</select>`),
    assetMarkupNode(`<select id="asset-filter-followup" data-label="Suivi" onchange="setAssetFilter('followup',this.value)"><option value="all" ${assetFollowup==='all'?'selected':''}>Tous</option><option value="active" ${assetFollowup==='active'?'selected':''}>Avec suivi actif</option><option value="none" ${assetFollowup==='none'?'selected':''}>Sans suivi actif</option></select>`)
  ];
  const reset=assetMarkupNode(`<button type="button" class="ui-filter-reset" onclick="resetAssetFilters()" ${activeFilters?'':'disabled'}>Réinitialiser</button>`);
  const action=SocleUI.PrimaryAction({label:'+ Ajouter un bien',ariaLabel:'Ajouter un bien'});
  action.setAttribute('onclick','assetForm()');
  return SocleUI.renderHTML(SocleUI.CompactFilterBar({
    className:'assets-filter-bar',
    label:'Filtrer les biens et le matériel',
    search,
    controls,
    reset,
    actions:[action],
    sheet:{id:'asset-filter-sheet',title:'Filtres',label:'Filtres Biens & matériel',toggleLabel:'Filtres',count:activeFilters}
  }));
}
function assetFilterContextHTML(categoryLabel,count){
  const context=SocleUI.ContextLine({items:[`${categoryLabel} · ${count} résultat(s)`]});
  context.classList.add('assets-filter-summary');
  return SocleUI.renderHTML(context);
}
fleetView=function(){
  const cats=[['vehicles','Flotte automobile'],['tools','Outillage'],['rentals','Locations'],['repairs','À réparer']];
  const base=categoryAssets(assetCategory),list=assetFilteredList(base),categoryLabel=cats.find(c=>c[0]===assetCategory)?.[1]||'Biens & matériel';
  const rows=list.map(a=>`<tr><td><strong>${esc(a.name)}</strong><small>${isVehicle(a)?esc(a.vehicle?.registration||'Immatriculation à renseigner'):esc(a.category)}</small></td><td>${esc(a.attached)}<small>${esc(a.responsible)}</small></td><td><span class="badge ${a.condition==='En service'?'green':'warn'}">${esc(a.condition)}</span></td>${assetCategory==='vehicles'?`<td>${fullDate(a.vehicle?.inspection)}<small>${vehicleAlertState(a.id,'inspection')}</small></td><td>${esc(a.vehicle?.insurer||'À renseigner')}<small>${fullDate(a.vehicle?.insuranceEnd)}</small></td>`:`<td>${a.mode}<small>${esc(a.provider)}</small></td><td>${fullDate(a.end)}</td>`}<td><button class="link" onclick="showAsset(${a.id})">Ouvrir ↗</button></td></tr>`).join('');
  return heading('Biens & matériel','Chaque catégorie a ses dossiers, ses contrats et ses échéances.',false)
    +`<div class="asset-categories">${cats.map(([key,label])=>`<button class="${key===assetCategory?'selected':''}" onclick="setAssetCategory('${key}')"><span>${label}</span><strong>${categoryAssets(key).length}</strong></button>`).join('')}</div>`
    +assetFilterBarHTML()
    +assetFilterContextHTML(categoryLabel,list.length)
    +`<section class="panel data-table"><table><thead><tr><th>${assetCategory==='vehicles'?'Véhicule / immatriculation':'Bien / lot'}</th><th>Rattachement / responsable</th><th>État</th>${assetCategory==='vehicles'?'<th>Contrôle technique</th><th>Assurance</th>':'<th>Financement / fournisseur</th><th>Échéance</th>'}<th></th></tr></thead><tbody>${rows}</tbody></table>${!list.length?'<div class="empty">Aucun bien ne correspond aux filtres.</div>':''}</section><p class="help-line">Un véhicule ou un outil peut aussi apparaître dans « Locations » ou « À réparer ». Il s’agit toujours du même dossier.</p>`;
};
function vehicleAlertState(id,field){const r=reminders.find(r=>r.linkType==='asset'&&r.linkId===id&&r.sourceField===field&&r.state!=='done');return r?reminderState(r)[0]:'Aucune alerte ouverte'}
showAsset=function(id){const a=assets.find(a=>a.id===id),v=a.vehicle;modal(a.name,`<span class="badge">${esc(a.category)} · ${a.mode}</span> <span class="badge ${a.condition==='En service'?'green':'warn'}">${esc(a.condition)}</span>${a.repairNote?`<p class="notice">Réparation : ${esc(a.repairNote)}</p>`:''}<div class="detail-row"><span>Rattachement</span><b>${esc(a.attached)}</b></div><div class="detail-row"><span>Responsable</span><b>${esc(a.responsible)}</b></div>${v?`<h3 class="detail-heading">Véhicule</h3><div class="detail-row"><span>Immatriculation / modèle</span><b>${esc(v.registration)}<br>${esc(v.model)}</b></div><div class="detail-row"><span>Première immatriculation</span><b>${fullDate(v.firstRegistration)}</b></div><div class="detail-row"><span>Kilométrage déclaré</span><b>${Number(v.mileage||0).toLocaleString('fr-BE')} km</b></div><h3 class="detail-heading">Contrôle technique & assurance</h3><div class="detail-row"><span>Prochain contrôle à confirmer</span><b>${fullDate(v.inspection)}</b></div><div class="detail-row"><span>Assureur / police</span><b>${esc(v.insurer||'À renseigner')}<br>${esc(v.policy||'')}</b></div><div class="detail-row"><span>Échéance d’assurance</span><b>${fullDate(v.insuranceEnd)}</b></div>`:''}<h3 class="detail-heading">Contrat & financement</h3><div class="detail-row"><span>Fournisseur / financeur</span><b>${esc(a.provider)}</b></div><div class="detail-row"><span>Référence</span><b>${esc(a.reference)}</b></div><div class="detail-row"><span>Depuis le</span><b>${fullDate(a.start)}</b></div>${a.mode!=='Achat'?`<div class="detail-row"><span>Fin du contrat</span><b>${fullDate(a.end)}</b></div><div class="detail-row"><span>${a.mode==='Location'?'Loyer mensuel déclaré HT':'Mensualité HT'}</span><b>${money(a.monthly)}</b></div>`:''}<h3 class="detail-heading">Contenu / équipement</h3><p class="notice">${esc(a.contents||'À renseigner')}</p><div class="section-heading"><h3>Alertes liées à ce dossier</h3><button class="link" onclick="reminderForm('','asset',${id})">+ Ajouter</button></div>${reminderRows(reminders.filter(r=>r.linkType==='asset'&&r.linkId===id&&r.state!=='done'))}<details class="detail-history"><summary>Alertes traitées (${reminders.filter(r=>r.linkType==='asset'&&r.linkId===id&&r.state==='done').length})</summary>${reminderRows(reminders.filter(r=>r.linkType==='asset'&&r.linkId===id&&r.state==='done'))}</details><h3 class="detail-heading">Documents référencés</h3>${a.docs.map(d=>`<p class="notice">${esc(d)}<br><small>Référence de démonstration · fichier non joint</small></p>`).join('')||'<p class="help-line">Aucun document référencé.</p>'}<div class="section-heading"><h3>Historique</h3><button class="link" onclick="historyForm(${id})">+ Ajouter un événement</button></div><div class="asset-history">${[...a.history].sort((a,b)=>b.date.localeCompare(a.date)).map(h=>`<p><small>${fullDate(h.date)}</small>${esc(h.text)}</p>`).join('')}</div><div class="modal-actions"><button class="btn primary" onclick="assetForm(${id})">Modifier le dossier</button></div>`)};
assetForm=function(id){const a=assets.find(a=>a.id===id)||{name:'',group:assetCategory==='vehicles'?'vehicles':'tools',category:assetCategory==='vehicles'?'Camionnette équipée':'Machine',mode:assetCategory==='rentals'?'Location':'Achat',provider:'',reference:'',start:reference,end:'',monthly:0,responsible:'',attached:'',contents:'',condition:assetCategory==='repairs'?'À réparer':'En service',repairNote:''};const v=a.vehicle||{};const inp=(key,label,type='text',value=a[key]||'',required=false)=>`<label>${label}<input name="${key}" type="${type}" ${required?'required':''} ${type==='number'?'min="0" step="0.01"':''} maxlength="300" value="${esc(value)}"></label>`;modal(id?'Modifier le dossier':'Ajouter un bien',`<form onsubmit="saveAsset(event,${id||0})">${inp('name','Nom du bien / véhicule','text',a.name,true)}<div class="form-two"><label>Catégorie<select name="group" onchange="document.querySelector('#vehicleFields').hidden=this.value!=='vehicles'"><option value="vehicles" ${a.group==='vehicles'?'selected':''}>Flotte automobile</option><option value="tools" ${a.group==='tools'?'selected':''}>Outillage</option></select></label><label>Type de bien<select name="category">${['Camionnette équipée','Camion équipé','Voiture','Remorque','Lot de machines','Machine','Outil'].map(c=>`<option ${a.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Financement<select name="mode">${['Achat','Leasing','Location'].map(m=>`<option ${m===a.mode?'selected':''}>${m}</option>`).join('')}</select></label><label>État<select name="condition">${['En service','À réparer','En réparation','Hors service'].map(s=>`<option ${s===a.condition?'selected':''}>${s}</option>`).join('')}</select></label>${inp('provider','Fournisseur / financeur')}${inp('reference','Référence contrat / facture')}${inp('start','Date de début / achat','date',a.start,true)}${inp('end','Fin de location / leasing','date')}${inp('monthly','Loyer mensuel / mensualité HT (€)','number',a.monthly)}${inp('responsible','Responsable','text',a.responsible,true)}</div>${inp('attached','Rattaché à (véhicule, équipe, local…)')}${inp('contents','Contenu / équipement permanent')}${inp('repairNote','Réparation : problème ou suivi')}<fieldset id="vehicleFields" ${a.group!=='vehicles'?'hidden':''}><legend>Fiche véhicule</legend><div class="form-two">${inp('registration','Immatriculation','text',v.registration||'')}${inp('model','Marque / modèle','text',v.model||'')}${inp('firstRegistration','Première immatriculation','date',v.firstRegistration||'')}${inp('mileage','Kilométrage déclaré','number',v.mileage||0)}${inp('inspection','Prochain contrôle technique','date',v.inspection||'')}${inp('insurer','Assureur','text',v.insurer||'')}${inp('policy','Numéro de police','text',v.policy||'')}${inp('insuranceEnd','Échéance d’assurance','date',v.insuranceEnd||'')}</div><p class="help-line">Les dates renseignées créent les alertes correspondantes sur l’accueil. Aucune périodicité réglementaire n’est calculée.</p></fieldset><p class="form-error" id="assetError" role="alert"></p><div class="modal-actions"><button class="btn primary">Enregistrer le dossier</button></div></form>`)};
function syncAssetReminder(a,field,date,title,kind){if(!date)return;let r=reminders.find(r=>r.linkType==='asset'&&r.linkId===a.id&&r.sourceField===field&&r.state!=='done');const done=reminders.find(r=>r.linkType==='asset'&&r.linkId===a.id&&r.sourceField===field&&r.state==='done'&&r.date===date);if(!r&&done)return;if(r){r.date=date;r.title=title;r.owner=a.responsible}else reminders.push({id:'asset-'+crypto.randomUUID(),title,date,kind,state:'todo',owner:a.responsible,note:'Date renseignée dans le dossier du bien, à confirmer sur les documents correspondants.',linkType:'asset',linkId:a.id,sourceField:field,completedAt:''})}
saveAsset=function(e,id){e.preventDefault();const f=new FormData(e.target);if(f.get('mode')!=='Achat'&&(!f.get('end')||f.get('end')<f.get('start'))){document.querySelector('#assetError').textContent='Renseignez une fin de contrat postérieure ou égale au début.';return}let a=assets.find(a=>a.id===id),d={};for(const k of ['name','group','category','mode','condition','provider','reference','start','end','responsible','attached','contents','repairNote'])d[k]=f.get(k).trim();if(!d.name||!d.responsible)return;d.monthly=d.mode==='Achat'?0:+f.get('monthly');if(!Number.isFinite(d.monthly)||d.monthly<0)return;if(d.mode==='Achat')d.end='';d.vehicle=null;if(d.group==='vehicles'){d.vehicle={};for(const k of ['registration','model','firstRegistration','inspection','insurer','policy','insuranceEnd'])d.vehicle[k]=f.get(k).trim();d.vehicle.mileage=+f.get('mileage')||0;}if(a){let changes=[];if(a.attached!==d.attached||a.responsible!==d.responsible)changes.push(`Rattachement : ${a.attached} (${a.responsible}) → ${d.attached} (${d.responsible}).`);if(a.condition!==d.condition)changes.push(`État : ${a.condition} → ${d.condition}.`);if(changes.length)a.history.push({date:new Date().toISOString().slice(0,10),text:changes.join(' ')});Object.assign(a,d)}else{a={id:Date.now(),...d,history:[{date:reference,text:'Dossier créé.'}],docs:[]};assets.push(a)}if(a.vehicle){syncAssetReminder(a,'inspection',a.vehicle.inspection,'Contrôle technique · '+a.name,'Contrôle technique');syncAssetReminder(a,'insuranceEnd',a.vehicle.insuranceEnd,'Assurance · '+a.name,'Assurance')}if(a.mode==='Location')syncAssetReminder(a,'end',a.end,'Retour de location · '+a.name,'Fin de location');if(a.condition==='À réparer'||a.condition==='En réparation')syncAssetReminder(a,'repair',reference,'Réparation · '+a.name,'Réparation');closeModal();render();showAsset(a.id);toast('Dossier mis à jour. Les échéances sont reliées à l’accueil.')};
