addAction=function(){reminderForm()};
const setStateBase=setState;setState=function(id,state){const r=reminders.find(r=>r.legacyId===id);if(r){changeReminder(r.id,state);return{id,state}}return setStateBase(id,state)};
const saveHistoryBase=saveHistory;saveHistory=function(e,id){saveHistoryBase(e,id);render()};
// Durable, private workspace state. Photos remain temporary previews.
let storageReady=false,storageRevision=0,savedSnapshot='',saveRunning=false,saveTimer=0,saveFailed=false,storageConflict=false,workspaceRecoveryKey='';
function workspaceRecoveryStorageKey(){return workspaceRecoveryKey||(globalThis.socleCurrentOrganizationId?'ouvrane:workspace-recovery:'+encodeURIComponent(String(globalThis.socleCurrentOrganizationId)):'')}
function workspaceRecoveryRead(){const key=workspaceRecoveryStorageKey();if(!key)return null;try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}}
function downloadWorkspaceRecovery(){const draft=workspaceRecoveryRead();if(!draft?.snapshot)return;const blob=new Blob([JSON.stringify(draft,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='socle-brouillon-non-synchronise-'+new Date(draft.savedAt||Date.now()).toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function preserveWorkspaceRecovery(snapshot){const key=workspaceRecoveryStorageKey();if(!key||!snapshot)return;try{localStorage.setItem(key,JSON.stringify({revision:storageRevision,savedAt:new Date().toISOString(),snapshot}))}catch{storageMessage('La copie de secours dépasse le stockage local. Gardez cette page ouverte et téléchargez vos changements si le bouton est disponible.',true)}}
function clearWorkspaceRecovery(){const key=workspaceRecoveryStorageKey();if(!key)return;try{localStorage.removeItem(key)}catch{}}
function discardWorkspaceRecovery(){if(!confirm('Supprimer définitivement la copie de secours de ce brouillon ?'))return;clearWorkspaceRecovery();storageMessage(storageConflict?'Conflit toujours actif. La copie locale a été supprimée. Ne rechargez pas tant que vos changements ne sont pas sauvegardés.':'Copie de secours supprimée.',storageConflict)}
function workspaceSnapshot(){return JSON.stringify({version:3,company,people,teams,jobs:jobs.map(j=>({...j,photos:[]})),assignments,quotes,assets,tasks,dossiers,reminders})}
function restoreWorkspace(s){company=s.company;people=s.people;teams=s.teams;jobs=s.jobs.map(j=>({...j,photos:[]}));assignments=s.assignments;quotes=s.quotes;assets=s.assets;tasks=s.tasks;dossiers=s.dossiers;reminders=s.reminders;document.querySelector('.workspace').firstChild.textContent=company.name;}
function storageMessage(text,error=false){const el=document.querySelector('#saveStatus');el.className=error?'save-warning':'save-ok';const recovery=workspaceRecoveryRead();el.innerHTML=`<span>${esc(text)}</span>${recovery?'<button class="link" onclick="downloadWorkspaceRecovery()">Télécharger ma copie de secours</button><button class="link" onclick="discardWorkspaceRecovery()">Supprimer la copie</button>':''}${error&&!storageConflict?'<button class="link" onclick="saveFailed=false;saveWorkspace()">Réessayer la sauvegarde</button>':''}`}
function scheduleSave(){if(!storageReady||storageConflict)return;const current=workspaceSnapshot();if(current===savedSnapshot&&!saveFailed)return;storageMessage('Modifications en cours de sauvegarde…');clearTimeout(saveTimer);saveTimer=setTimeout(saveWorkspace,450)}
async function saveWorkspace(){if(!storageReady||saveRunning||storageConflict)return;const snapshot=workspaceSnapshot();if(snapshot===savedSnapshot){storageMessage('Toutes les modifications sont sauvegardées.');return}saveRunning=true;saveFailed=false;storageMessage('Sauvegarde en cours…');try{let body;if(typeof serverJson==='function')body=await serverJson('/api/state',{method:'PUT',body:JSON.stringify({revision:storageRevision,state:JSON.parse(snapshot)})});else{const r=await fetch('/api/state',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({revision:storageRevision,state:JSON.parse(snapshot)})});body=await r.json();if(!r.ok){const error=Error(body.error||'Sauvegarde indisponible.');error.status=r.status;throw error}}storageRevision=body.revision;savedSnapshot=snapshot;storageMessage('Toutes les modifications sont sauvegardées.')}catch(e){if(e.status===409)storageConflict=true;saveFailed=true;preserveWorkspaceRecovery(snapshot);storageMessage(storageConflict?'Une autre fenêtre a modifié le dossier. Vos changements restent ici et une copie de secours est conservée sur cet appareil. Téléchargez-la avant de recharger.':e.message||'Sauvegarde indisponible. Vos modifications restent dans cette page.',true)}finally{saveRunning=false;if(!saveFailed&&workspaceSnapshot()!==savedSnapshot)scheduleSave()}}
const renderBase=render;render=function(){renderBase();scheduleSave()};
// These actions change state without always rendering the main view.
const toastBase=toast;toast=function(msg){toastBase(msg);scheduleSave()};
window.addEventListener('beforeunload',e=>{if(storageReady&&workspaceSnapshot()!==savedSnapshot){preserveWorkspaceRecovery(workspaceSnapshot());e.preventDefault();e.returnValue=''}});
async function loadWorkspace(){globalThis.socleWorkspaceLoading=true;storageReady=false;document.querySelector('#main').innerHTML='<div class="empty">Chargement de votre entreprise…</div>';document.querySelector('#nav').setAttribute('inert','');try{let body;if(typeof serverJson==='function')body=await serverJson('/api/state');else{const r=await fetch('/api/state',{cache:'no-store'});body=await r.json();if(!r.ok)throw Error(body.error||'Chargement indisponible.')}if(typeof globalThis.syncSocleSessionOrganization==='function')globalThis.syncSocleSessionOrganization(body.access?.userId||'',body.organizationId||'');globalThis.socleLimitedSession=Boolean(body.readOnly);globalThis.socleContactsAllowed=Boolean(body.contactsAllowed);globalThis.socleCurrentAccess=body.access||null;if(!globalThis.socleAccessPreview)globalThis.socleAuthenticatedAccess=body.access||null;globalThis.socleAccessPreviewVerified=Boolean(body.preview===true&&globalThis.socleAccessPreview&&body.access?.roleCode===globalThis.socleAccessPreview.roleCode);if(globalThis.socleAccessPreview&&!body.state){globalThis.socleAccessPreviewVerified=false;throw Error("Aucun dossier enregistré ne permet de prévisualiser cet accès actuellement.")}if(globalThis.socleAccessPreview?.memberKey&&typeof sessionAccessKey!=='undefined')sessionAccessKey=globalThis.socleAccessPreview.memberKey;else if(body.role&&body.role!=='OWNER'&&body.localIdentity?.personId&&typeof sessionAccessKey!=='undefined')sessionAccessKey='person:'+body.localIdentity.personId;else if(body.role==='OWNER'&&typeof sessionAccessKey!=='undefined')sessionAccessKey='owner';if(body.state)restoreWorkspace(body.state);else if(globalThis.initializeWorkspace)initializeWorkspace();if(typeof globalThis.applyCurrentServerAccess==='function')globalThis.applyCurrentServerAccess(body.access||null);const optionalLoads=[['pointages',globalThis.loadServerTimeEntries],['données terrain',globalThis.loadServerFieldData]];for(const [label,loader] of optionalLoads){if(typeof loader!=='function')continue;try{await loader({renderAfter:false})}catch(error){console.warn('Chargement partiel OUVRANE · '+label,error)}}storageRevision=body.revision;savedSnapshot=body.state?workspaceSnapshot():'';storageReady=globalThis.socleAccessPreview?false:true;globalThis.socleWorkspaceLoading=false;render();if(body.state)storageMessage(body.readOnly?'Accès limité chargé · les modifications globales sont désactivées.':'Dossiers chargés · sauvegarde automatique activée.');else scheduleSave()}catch(e){document.querySelector('#main').innerHTML=`<section class="panel load-error"><h2>Impossible de charger votre espace</h2><p>${esc(e.message)}</p><button class="btn primary" onclick="loadWorkspace()">Réessayer</button></section>`;document.querySelector('#saveStatus').textContent='Aucune modification effectuée.'}finally{document.querySelector('#nav').removeAttribute('inert')}globalThis.socleWorkspaceLoading=false;document.body.classList.remove('socle-loading');}
// Wait for all feature modules before restoring or initializing a workspace.
window.addEventListener('DOMContentLoaded',loadWorkspace,{once:true});

