function leaveUsed(p){return p.hr.leave.reduce((n,x)=>n+(Number(x.days)||0),0)}
function personEventRows(items,empty){return items.length?`<div class="person-events">${[...items].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(x=>`<div><span><strong>${esc(x.label||'Événement')}</strong><small>${fullDate(x.date)}${x.note?' · '+esc(x.note):''}</small></span>${x.days?`<b>${x.days} jour(s)</b>`:''}</div>`).join('')}</div>`:`<p class="person-empty">${empty}</p>`}
function showPersonDossier(id){const p=getPerson(id);if(!p)return;ensurePersonData();const team=teams.find(t=>t.members.includes(id)),remaining=Math.max(0,p.hr.leaveTotal-leaveUsed(p));modal(p.name,`<div class="person-dossier-head">${face(p)}<div><span class="badge">${esc(p.category||'Ouvrier')} · ${esc(p.contract)}</span><p>${esc(p.role)}${team?' · '+esc(team.name):''}</p></div></div><div class="person-kpis"><div><small>Congés restants</small><strong>${remaining}</strong><span>sur ${p.hr.leaveTotal} jours</span></div><div><small>Retards</small><strong>${p.hr.lateness.length}</strong><span>enregistrés</span></div><div><small>Formations</small><strong>${p.training.length}</strong><span>déclarées</span></div><div><small>Permis</small><strong>${p.hr.permits.length}</strong><span>renseignés</span></div></div><div class="person-section"><div class="section-heading"><h3>Contrat & identité</h3><button class="link" onclick="personEditForm(${id})">Modifier la fiche</button></div><div class="detail-row"><span>Date d’entrée</span><b>${fullDate(p.start)}</b></div><div class="detail-row"><span>Fin de contrat</span><b>${fullDate(p.end)}</b></div><div class="detail-row"><span>Anniversaire</span><b>${fullDate(p.birth)}</b></div></div><div class="person-section"><div class="section-heading"><h3>Congés</h3><button class="link" onclick="personRecordForm(${id},'leave')">+ Enregistrer</button></div>${personEventRows(p.hr.leave,'Aucun congé enregistré.')}</div><div class="person-section"><div class="section-heading"><h3>Retards & absences</h3><button class="link" onclick="personRecordForm(${id},'lateness')">+ Ajouter</button></div>${personEventRows(p.hr.lateness,'Aucun retard ou absence enregistré.')}</div><div class="person-section"><div class="section-heading"><h3>Tickets & remarques</h3><button class="link" onclick="personRecordForm(${id},'ticket')">+ Ajouter</button></div>${personEventRows(p.hr.tickets,'Aucun ticket ouvert.')}</div><div class="person-section"><div class="section-heading"><h3>Formations</h3><button class="link" onclick="personRecordForm(${id},'training')">+ Ajouter</button></div><div class="training-tags">${p.training.length?p.training.map(t=>`<span>${esc(t)}</span>`).join(''):'<span>Aucune formation renseignée</span>'}</div></div><div class="person-section"><div class="section-heading"><h3>Permis & habilitations</h3><button class="link" onclick="personRecordForm(${id},'permit')">+ Ajouter</button></div>${p.hr.permits.length?`<div class="permit-grid">${p.hr.permits.map(x=>`<div><strong>${esc(x.name)}</strong><span>${esc(x.number||'Référence non renseignée')}</span><small>Valable jusqu’au ${fullDate(x.expires)}</small></div>`).join('')}</div>`:'<p class="person-empty">Aucun permis ou habilitation renseigné.</p>'}</div><div class="person-section"><div class="section-heading"><h3>Alertes liées</h3><button class="link" onclick="reminderForm('','person',${id})">+ Ajouter</button></div>${reminderRows(reminders.filter(r=>r.linkType==='person'&&r.linkId===id&&r.state!=='done'))}</div>`)}

function personRecordForm(id,type){const labels={leave:['Congé','Motif ou intitulé'],lateness:['Retard ou absence','Motif'],ticket:['Ticket ou remarque','Intitulé'],training:['Formation','Intitulé'],permit:['Permis ou habilitation','Intitulé']};modal(`Ajouter · ${labels[type][0]}`,`<form onsubmit="savePersonRecord(event,${id},'${type}')"><label>${labels[type][1]}<input name="label" required maxlength="120"></label>${type==='leave'?'<label>Nombre de jours<input name="days" type="number" min="0.5" step="0.5" required value="1"></label>':''}${type==='permit'?'<div class="form-two"><label>Numéro / référence<input name="number" maxlength="80"></label><label>Date de validité<input name="expires" type="date"></label></div>':type==='training'?'':'<label>Date<input name="date" type="date" required value="'+reference+'"></label>'}${!['training','permit'].includes(type)?'<label>Note<input name="note" maxlength="300"></label>':''}<div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>`)}
function savePersonRecord(e,id,type){e.preventDefault();const f=new FormData(e.target),p=getPerson(id),label=f.get('label').trim();if(!p||!label)return;if(type==='training'){if(!p.training.includes(label))p.training.push(label)}else if(type==='permit')p.hr.permits.push({name:label,number:f.get('number').trim(),expires:f.get('expires')});else{const row={label,date:f.get('date'),note:f.get('note').trim()};if(type==='leave'){row.days=+f.get('days');p.hr.leave.push(row)}else if(type==='lateness')p.hr.lateness.push(row);else p.hr.tickets.push(row);p.hr.history.push({date:row.date,label})}closeModal();showPersonDossier(id);toast('Dossier du travailleur mis à jour.')}

function newsView(){const year=reference.slice(0,4),list=newsFilter==='relevant'?newsItems.filter(n=>n.important):newsFilter==='all'?newsItems:newsItems.filter(n=>String(n.year)===year);return heading('Actualités & réglementations','Les changements importants et leurs conséquences pour l’entreprise.',false)+`<div class="news-notice"><strong>Module en préparation</strong><span>Les exemples montrent le fonctionnement. Toute information réelle affichera sa source officielle et sa date de vérification.</span></div><div class="section-heading"><div class="filter-pills">${[['relevant','Cela vous concerne'],['all','À connaître'],['year','Récapitulatif '+year]].map(([v,l])=>`<button class="${newsFilter===v?'selected':''}" onclick="newsFilter='${v}';render()">${l}</button>`).join('')}</div><span class="subtle">${list.length} information(s)</span></div><div class="news-grid">${list.map(n=>`<article class="news-card"><div class="news-top"><span class="badge">${esc(n.category)}</span><time>${fullDate(n.date)}</time></div><h2>${esc(n.title)}</h2><p>${esc(n.summary)}</p><dl><div><dt>Entreprises concernées</dt><dd>${esc(n.applies)}</dd></div><div><dt>Impact possible</dt><dd>${esc(n.impact)}</dd></div><div><dt>À faire</dt><dd>${esc(n.action)}</dd></div></dl><div class="news-source"><span>${esc(n.source)}</span><button class="btn" onclick="newsToReminder('${n.id}')">Ajouter à mes alertes</button></div></article>`).join('')}</div>`}
function newsToReminder(id){const n=newsItems.find(x=>x.id===id);if(!n)return;if(reminders.some(r=>r.newsId===id&&r.state!=='done')){toast('Cette actualité est déjà dans vos alertes.');return}reminders.push({id:'news-'+crypto.randomUUID(),newsId:id,title:n.title,date:reference,state:'todo',kind:n.category,owner:company.manager||company.adminContact||'Responsable à définir',note:`${n.action} Source : ${n.source}.`,linkType:'company',linkId:0,completedAt:''});render();toast('Actualité ajoutée aux alertes de l’entreprise.')}

render=function(){document.querySelector('#nav').innerHTML=tabs2.map(([v,l])=>`<button class="${view===v?'active':''}" ${view===v?'aria-current="page"':''} onclick="navigate('${v}')">${l}</button>`).join('');document.querySelector('#main').innerHTML=({planning,home:planning,people:peopleView,jobs:jobsView,fleet:fleetView,quotes:quotesView,news:newsView,actions,documents,company:companyView,dossiers:dossierView}[view]||planning)();scheduleSave()};
